(()=>{const preference=matchMedia("(prefers-reduced-motion: reduce)");const running=new Set;document.querySelectorAll(".research-details").forEach(details=>{const summary=details.querySelector("summary");const card=details.closest(".research-card");let targetOpen=details.open;let animation=null;card.classList.toggle("is-expanded",targetOpen);summary.addEventListener("click",event=>{event.preventDefault();const from=details.getBoundingClientRect().height;targetOpen=!targetOpen;if(animation){running.delete(animation);animation.cancel();animation=null}card.classList.toggle("is-expanded",targetOpen);if(preference.matches||document.hidden){details.style.height="";details.style.overflow="";details.open=targetOpen;return}details.open=true;details.style.height="";const to=targetOpen?details.getBoundingClientRect().height:summary.getBoundingClientRect().height+parseFloat(getComputedStyle(details).borderTopWidth);details.style.height=`${from}px`;details.style.overflow="hidden";const current=details.animate([{height:`${from}px`},{height:`${to}px`}],{duration:Math.min(520,Math.max(280,Math.abs(to-from)*.45+280)),easing:"cubic-bezier(.22,.68,.22,1)",fill:"both"});animation=current;running.add(current);current.onfinish=()=>{if(animation!==current)return;details.open=targetOpen;details.style.height="";details.style.overflow="";current.cancel();running.delete(current);animation=null}});details.addEventListener("toggle",()=>{if(!animation){targetOpen=details.open;card.classList.toggle("is-expanded",targetOpen)}})});const finishWhenHidden=()=>{if(preference.matches||document.hidden)running.forEach(animation=>animation.finish())};preference.addEventListener("change",finishWhenHidden);document.addEventListener("visibilitychange",finishWhenHidden)})();
